"""Build the self-contained live report shell for stress-activation fitting."""
# ruff: noqa: RUF001

from __future__ import annotations

from pathlib import Path

import pydantic_settings as ps
from experiment import Profile

from liblaf import cherries


class Config(cherries.BaseConfig):
    model_config = ps.SettingsConfigDict(cli_parse_args=True, cli_kebab_case=True)
    output: Path = Path("site/index.html")


HTML = r"""<!doctype html>
<html lang="en">
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Stress–activation loss study</title>
<style>
:root{--ink:#17202a;--muted:#5f6b76;--paper:#f7f5ef;--card:#fffdfa;--line:#ded9ce;--blue:#1878b5;--orange:#d56820;--green:#28754a;--red:#b53b32;--violet:#6d4b9a}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.45 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}main{max-width:1320px;margin:auto;padding:20px}h1,h2,h3,p{margin-top:0}h1{font-size:clamp(1.65rem,4vw,2.55rem);line-height:1.12;margin-bottom:.4rem}h2{font-size:1.2rem;margin-bottom:.55rem}h3{font-size:1rem;margin-bottom:.3rem}.lede,.muted{color:var(--muted)}.banner{display:flex;gap:12px;align-items:center;justify-content:space-between;border:1px solid var(--line);padding:12px 14px;background:var(--card);border-radius:12px;margin:18px 0}.pill{display:inline-block;border-radius:999px;padding:3px 9px;font-size:.8rem;font-weight:700;background:#e8edf0;color:#33414b}.pill.running{background:#e3f0fa;color:#176798}.pill.done{background:#e4f2e8;color:#1d693c}.pill.failed{background:#f8e3e0;color:#9d3029}.setup{display:grid;grid-template-columns:repeat(auto-fit,minmax(235px,1fr));gap:12px;margin:16px 0 22px}.panel,.stage{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:14px}.panel ul{padding-left:19px;margin:.4rem 0}.matrix{display:grid;grid-template-columns:120px repeat(2,minmax(0,1fr));gap:8px;align-items:stretch}.matrix-head{font-size:.88rem;font-weight:750;padding:9px 6px;color:var(--muted)}.rowlabel{font-size:.9rem;font-weight:750;padding:13px 6px;border-bottom:1px solid var(--line)}.stage{min-height:190px}.stage[data-state="not-started"]{opacity:.72}.stage-head{display:flex;gap:8px;align-items:start;justify-content:space-between}.stage-head h3{margin:0}.meta{font-size:.82rem;color:var(--muted)}.metrics{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:4px 12px;margin:10px 0;font-size:.86rem}.metrics dt{color:var(--muted)}.metrics dd{margin:0;font-variant-numeric:tabular-nums;font-weight:650}.spark-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;border-top:1px solid var(--line);padding-top:8px}.spark{margin:0}.spark figcaption{font-size:.73rem;color:var(--muted)}.spark svg{display:block;width:100%;height:52px}.empty{color:var(--muted);font-size:.88rem;margin:10px 0}.failure{color:var(--red);font-size:.88rem;white-space:pre-wrap}.images{display:flex;gap:6px;flex-wrap:wrap;margin-top:9px}.image-link{font-size:.78rem;color:#176798}.gallery{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin:12px 0 24px}.gallery a{display:block;color:var(--ink);font-weight:700}.gallery img{display:block;width:100%;margin-top:5px;border:1px solid var(--line);border-radius:9px}.compact{width:100%;border-collapse:collapse;background:var(--card);border:1px solid var(--line);border-radius:10px;overflow:hidden}.compact th,.compact td{padding:8px;text-align:left;border-bottom:1px solid var(--line);font-variant-numeric:tabular-nums}.compact th{font-size:.84rem;color:var(--muted)}.foot{font-size:.82rem;color:var(--muted);margin:20px 0 0}.key{display:flex;gap:12px;flex-wrap:wrap;font-size:.86rem}.dot{display:inline-block;width:10px;height:10px;border-radius:50%;margin-right:4px}.dot.pos{background:var(--blue)}.dot.norm{background:var(--orange)}.dot.rough{background:var(--violet)}.dot.det{background:var(--green)}@media(max-width:720px){main{padding:14px}.matrix{grid-template-columns:1fr}.matrix-head{display:none}.rowlabel{border:none;padding:16px 3px 2px}.stage{min-height:0}.banner{align-items:flex-start;flex-direction:column}.spark-grid,.gallery{grid-template-columns:1fr}.compact{font-size:.85rem}}
</style>
<main>
  <header>
    <h1>Stress–activation loss study</h1>
    <p class="lede">Live record of staged inverse fitting. Values appear only after the runner writes them; this page never estimates missing results.</p>
  </header>
  <section class="banner" aria-live="polite"><div><strong id="overall">Waiting for runner status</strong><div class="muted" id="updated">No status.json has been read yet.</div><div class="failure" id="overall-failure" hidden></div></div><span class="pill" id="phase">not started</span></section>
  <section class="setup">
    <article class="panel"><h2>Fixed model</h2><ul><li>Shared strong smoothness weight</li><li>Stable Neo-Hookean + activation tensor <em>Q</em></li><li>No skin mechanics</li><li>Four activation parameterizations across the stage chain</li></ul></article>
    <article class="panel"><h2>Updated elastic constants</h2><ul><li>Fat: 11.2 kPa</li><li>Muscle: 12 kPa</li><li>Aponeurosis: 1.693 MPa</li><li>Poisson ratio: 0.49</li></ul></article>
    <article class="panel"><h2>Loss columns</h2><ul><li>Position: <em>L</em><sub>pos</sub> / ℓ<sub>ref</sub>²</li><li>ℓ<sub>ref</sub> = 13.236093 mm</li><li>Normal weight: 0 or 1</li><li id="smooth-weight">Smoothness weight: pilot pending</li><li>Reported metrics remain separate from loss terms</li></ul></article>
  </section>
  <section id="calibration" hidden><h2>Strong-smoothness calibration</h2><p class="muted">Observed pilot only. A calibrated weight appears only after the runner writes it.</p><div id="calibration-card"></div></section>
  <section id="calibration-outcome" hidden><h2>Selected calibration tradeoff</h2><p class="muted" id="calibration-context"></p><table class="compact"><thead><tr><th>Loss</th><th>Squared roughness / unregularized</th><th>Retained data-loss improvement</th></tr></thead><tbody id="calibration-rows"></tbody></table></section>
  <section id="comparison" hidden><h2>Shared-scale result atlas</h2><p class="muted">Only supplied comparison images are shown. Blank atlas cells mean no accepted saved state was available.</p><div class="gallery" id="comparison-gallery"></div></section>
  <section><h2>Stage chain</h2><p class="muted">Each row is a stage; columns differ only in normal-loss weight. A card remains “not started” until a matching stage record arrives.</p><div class="key"><span><i class="dot pos"></i>position contribution</span><span><i class="dot norm"></i>normal contribution</span><span><i class="dot rough"></i>activation roughness</span><span><i class="dot det"></i>minimum det(F)</span></div><div class="matrix" id="matrix"></div></section>
  <p class="foot">Refreshes every 5 seconds. Stress maps and other stage images appear only when their paths are supplied by the runner.</p>
</main>
<script>
const STAGES=[1,2,3,4], COLUMNS=[{id:'0',title:'Position loss',note:'normal weight 0'},{id:'1',title:'Position + normal',note:'normal weight 1'}], MODE_STAGES={symmetric6:1,psd6:2,rankone_fixed:3,rankone_learned:4};
const matrix=document.querySelector('#matrix');
const val=x=>typeof x==='number'&&Number.isFinite(x), fmt=(x,d=4)=>val(x)?x.toLocaleString(undefined,{maximumFractionDigits:d}):'—';
const esc=x=>String(x??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
function lossId(x){const s=String(x??'').toLowerCase();return ({l2:'0',normal:'1','0':'0','1':'1'})[s]??null}
function state(s){const x=String(s??'not-started').toLowerCase();if(x.includes('not_started')||x.includes('not started'))return'not-started';if(x.includes('blocked')||x.includes('stalled')||x.includes('incomplete')||x.includes('fail'))return'failed';if(x.includes('completed')||x==='passed'||x==='pass')return'done';return x.includes('run')||x.includes('prepar')?'running':'not-started'}
function stageRecord(all,row,col){return all.find(s=>MODE_STAGES[s.mode]===row&&lossId(s.loss)===col)}
function values(history,key){return history.map(r=>[r.step,r[key]]).filter(p=>val(p[0])&&val(p[1]))}
function spark(name,color,points){if(points.length<2)return '';const width=180,height=50,pad=4,xs=points.map(p=>p[0]),ys=points.map(p=>p[1]),xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=Math.min(...ys),ymax=Math.max(...ys),low=ymin===ymax?ymin-1:ymin,high=ymin===ymax?ymax+1:ymax,xy=([x,y])=>`${pad+(x-xmin)*(width-2*pad)/(xmax-xmin||1)},${height-pad-(y-low)*(height-2*pad)/(high-low)}`;return `<figure class="spark"><figcaption>${name}: ${fmt(ys[0])} → ${fmt(ys.at(-1))}; range ${fmt(ymin)}–${fmt(ymax)}</figcaption><svg viewBox="0 0 ${width} ${height}" role="img" aria-label="${esc(name)} trend"><polyline fill="none" stroke="${color}" stroke-width="2" points="${points.map(xy).join(' ')}"/></svg></figure>`}
function charts(history){if(!Array.isArray(history)||history.length<2)return '<p class="empty">No history has been written.</p>';const specs=[['total objective','#263d52','objective'],['position contribution','#1878b5','position_contribution'],['normal contribution','#d56820','normal_contribution'],['roughness R','#6d4b9a','activation_smoothness'],['minimum det(F)','#28754a','detF_min']];const html=specs.map(([n,c,k])=>spark(n,c,values(history,k))).filter(Boolean).join('');return html?`<div class="spark-grid">${html}</div>`:'<p class="empty">No plottable components have been written.</p>'}
function failureText(failure){if(!failure)return '';const text=typeof failure==='string'?failure:failure.message??JSON.stringify(failure);return `<p class="failure">${esc(text)}</p>`}
function imageLinks(images){if(!images||typeof images!=='object')return '';const links=Object.entries(images).map(([name,value])=>[name,typeof value==='string'?value:value?.path]).filter(([,path])=>typeof path==='string'&&path.length).map(([name,path])=>`<a class="image-link" href="${esc(path)}" target="_blank" rel="noopener">${esc(name)}</a>`).join('');return links?`<div class="images">${links}</div>`:''}
function comparison(images){const entries=Object.entries(images??{}).map(([name,value])=>[name,typeof value==='string'?value:value?.path]).filter(([,path])=>typeof path==='string'&&path.length);const section=document.querySelector('#comparison'),gallery=document.querySelector('#comparison-gallery');section.hidden=!entries.length;gallery.innerHTML=entries.map(([name,path])=>`<a href="${esc(path)}" target="_blank" rel="noopener">${esc(name)}<img src="${esc(path)}" alt="${esc(name)}"></a>`).join('')}
function calibration(progress){const section=document.querySelector('#calibration'),slot=document.querySelector('#calibration-card');section.hidden=!progress;if(!progress){slot.innerHTML='';return}const r=progress,m=r.metrics||{},h=r.history||[],last=h.at?.(-1)||{},get=k=>m[k]??last[k];slot.innerHTML=`<article class="stage" data-state="${state(r.status)}"><div class="stage-head"><div><h3>${esc(r.id??'calibration pilot')}</h3><div class="meta">${esc(r.status??'unknown')}</div></div><span class="pill ${state(r.status)}">${esc(r.status??'unknown')}</span></div><dl class="metrics"><dt>update</dt><dd>${r.step??last.step??'—'} / ${r.budget??'—'}</dd><dt>objective</dt><dd>${fmt(get('objective'))}</dd><dt>position RMS</dt><dd>${val(get('fit_rms_mm'))?fmt(get('fit_rms_mm'),3)+' mm':'—'}</dd><dt>normal RMS</dt><dd>${val(get('normal_angle_rms_deg'))?fmt(get('normal_angle_rms_deg'),3)+'°':'—'}</dd><dt>roughness R</dt><dd>${fmt(get('activation_smoothness'))}</dd><dt>min det(F)</dt><dd>${fmt(get('detF_min'))}</dd></dl>${charts(h)}${failureText(r.failure)}</article>`}
function calibrationOutcome(calibration){const section=document.querySelector('#calibration-outcome'),context=document.querySelector('#calibration-context'),rows=document.querySelector('#calibration-rows'),weight=calibration?.selected_weight,candidate=Array.isArray(calibration?.candidates)?calibration.candidates.find(c=>val(c.weight)&&val(weight)&&Math.abs(c.weight-weight)<=1e-12*Math.max(1,Math.abs(weight))):null,branches=candidate?.branches;if(!candidate||!branches?.l2||!branches?.normal){section.hidden=true;rows.innerHTML='';return}const pilot=calibration.pilot_steps,losses=[['L2',branches.l2],['L2 + normal',branches.normal]];if(!losses.every(([,b])=>val(b.roughness_ratio_to_unregularized)&&val(b.data_progress_retained))){section.hidden=true;rows.innerHTML='';return}section.hidden=false;context.textContent=`Selected fixed smoothness weight ${fmt(weight,8)} from matched ${pilot??'recorded'}-accepted-update pilots. This table reports the stated calibration criterion and retained data-fit progress; it is not a final-fit result.`;rows.innerHTML=losses.map(([name,b])=>`<tr><td>${name}</td><td>${fmt(b.roughness_ratio_to_unregularized,4)}</td><td>${fmt(100*b.data_progress_retained,1)}%</td></tr>`).join('')}
function card(record,row,col){const r=record||{},m=r.metrics||{},h=r.history||[],s=state(r.status),last=h.at?.(-1)||{},get=k=>m[k]??last[k],title=`Stage ${row}`;return `<article class="stage" data-state="${s}"><div class="stage-head"><div><h3>${title}</h3><div class="meta">${esc(r.mode??'awaiting stage configuration')}</div></div><span class="pill ${s}">${esc(r.status??'not started')}</span></div><dl class="metrics"><dt>update</dt><dd>${r.step??last.step??'—'} / ${r.budget??'—'}</dd><dt>objective</dt><dd>${fmt(get('objective'))}</dd><dt>position RMS</dt><dd>${val(get('fit_rms_mm'))?fmt(get('fit_rms_mm'),3)+' mm':'—'}</dd><dt>normal RMS</dt><dd>${val(get('normal_angle_rms_deg'))?fmt(get('normal_angle_rms_deg'),3)+'°':'—'}</dd><dt>roughness R</dt><dd>${fmt(get('activation_smoothness'))}</dd><dt>min det(F)</dt><dd>${fmt(get('detF_min'))}</dd></dl>${charts(h)}${failureText(r.failure)}${imageLinks(r.images)}</article>`}
function render(data){const stages=Array.isArray(data.stages)?data.stages:[];document.querySelector('#overall').textContent=data.overall?.status??data.overall??data.status??'Waiting for runner status';document.querySelector('#updated').textContent=data.updated_at?`Updated ${data.updated_at}`:'No timestamp supplied.';const p=document.querySelector('#phase');p.textContent=data.phase??'not started';p.className='pill '+state(data.phase);const failure=data.failure??data.calibration_progress?.failure,notice=document.querySelector('#overall-failure');notice.hidden=!failure;notice.textContent=failure?(typeof failure==='string'?failure:failure.message??JSON.stringify(failure)):'';const weight=data.protocol?.smooth_weight;document.querySelector('#smooth-weight').textContent=val(weight)?`Smoothness weight: ${fmt(weight,8)} (selected)`:`Smoothness weight: ${weight??'pilot pending'}`;calibration(data.calibration_progress);calibrationOutcome(data.protocol?.calibration);comparison(data.comparison_images);let html='<div></div>'+COLUMNS.map(c=>`<div class="matrix-head"><strong>${c.title}</strong><br>${c.note}</div>`).join('');for(const row of STAGES){html+=`<div class="rowlabel">Stage ${row}<br><span class="meta">chain ${row===1?'start':`${row-1} → ${row}`}</span></div>`+COLUMNS.map(c=>card(stageRecord(stages,row,c.id),row,c.id)).join('')}matrix.innerHTML=html}
async function refresh(){try{const r=await fetch(`status.json?_=${Date.now()}`,{cache:'no-store'});if(!r.ok)throw Error(`status unavailable (${r.status})`);render(await r.json())}catch(e){render({overall:{status:'Waiting for runner status'},phase:'not started',updated_at:e.message,stages:[]})}}
refresh();setInterval(refresh,5000);
</script>"""


def main(config: Config) -> None:
    path = config.output
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_suffix(".tmp")
    temporary.write_text(HTML, encoding="utf-8")
    temporary.replace(path)


if __name__ == "__main__":
    cherries.main(main, profile=Profile)
